function reverseEvenLengthGroups(head) {
  let tail = head;
  let groupSize = 2;
  while (tail.next) {
    const first = tail.next;
    let after = first;
    let length = 0;
    while (after && length < groupSize) {
      after = after.next;
      length++;
    }
    if (length % 2 === 0) {
      let prev = after;
      let curr = first;
      for (let k = 0; k < length; k++) {
        const next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
      }
      tail.next = prev;
      tail = first;
    } else {
      for (let k = 0; k < length; k++) {
        tail = tail.next;
      }
    }
    groupSize++;
  }
  return head;
}

