function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const top = rand() < 0.7 ? 9 : 100000;
    return [Array.from({ length: int(1, 16) }, () => int(0, top))];
  }
  const n = rand() < 0.5 ? 2000 : int(1900, 2000);
  return [Array.from({ length: n }, () => int(0, 100000))];
